#top-settings-holder>.drawer:nth-child(6) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(6) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(7) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(7) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(8) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(8) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(9) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(9) .drawer-icon::before{opacity:0!important;}
#send_but{background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-2.webp') center/contain no-repeat!important;font-size:0!important;}#send_but::before{opacity:0;}
#chat .mes .mes_buttons .extraMesButtons{position:absolute;right:40px;top:0;width:76px;max-width:76px;flex-basis:auto;padding:6px;background:rgba(248,252,255,.98);border:1px solid #c5d9e7;border-radius:12px;z-index:5;}
